create or replace function public.mensaje_json(m public.mensajes_whatsapp)returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('id',m.id,'conversationId',m.conversacion_id,'patientId',m.paciente_id,'patientName',coalesce(concat_ws(' ',p.nombres,p.apellido_paterno,p.apellido_materno),'Número no identificado'),'appointmentId',m.cita_id,'encounterId',m.atencion_id,'direction',m.direccion,'type',m.tipo,'content',m.contenido,'status',m.estado,'scheduledFor',m.programado_para,'intent',m.intencion,'reviewRequired',m.requiere_revision,'errorDetail',m.error_detalle,'attempts',m.intentos,'maxAttempts',m.max_intentos,'lastAttemptAt',m.ultimo_intento_en,'createdAt',m.creado_en,'sentAt',m.enviado_en)from public.pacientes p where p.id=m.paciente_id union all select jsonb_build_object('id',m.id,'conversationId',m.conversacion_id,'patientName','Número no identificado','direction',m.direccion,'type',m.tipo,'content',m.contenido,'status',m.estado,'scheduledFor',m.programado_para,'intent',m.intencion,'reviewRequired',m.requiere_revision,'errorDetail',m.error_detalle,'attempts',m.intentos,'maxAttempts',m.max_intentos,'lastAttemptAt',m.ultimo_intento_en,'createdAt',m.creado_en,'sentAt',m.enviado_en)where m.paciente_id is null $$;
create or replace function public.seguimiento_json(f public.seguimientos_postconsulta)returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('id',f.id,'patientId',f.paciente_id,'patientName',concat_ws(' ',p.nombres,p.apellido_paterno,p.apellido_materno),'encounterId',f.atencion_id,'messageId',f.mensaje_id,'scheduledFor',f.programado_para,'status',f.estado,'response',f.respuesta,'classification',f.clasificacion,'alertReason',f.motivo_alerta,'reviewedBy',f.revisado_por,'reviewedAt',f.revisado_en,'version',f.version)from public.pacientes p where p.id=f.paciente_id $$;
create or replace function public.listar_mensajes()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('SEGUIMIENTO_LEER')then raise exception using errcode='42501',message='No autorizado para consultar mensajes';end if;select coalesce(jsonb_agg(x.data),'[]'::jsonb)into result from(select public.mensaje_json(m)data from public.mensajes_whatsapp m order by m.creado_en desc limit 50)x;return result;end $$;
create or replace function public.listar_seguimientos()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin if not public.has_permission('SEGUIMIENTO_LEER')then raise exception using errcode='42501',message='No autorizado para consultar seguimientos';end if;select coalesce(jsonb_agg(public.seguimiento_json(f)order by f.programado_para desc),'[]'::jsonb)into result from public.seguimientos_postconsulta f;return result;end $$;
create or replace function public.programar_mensaje(paciente_id bigint,contenido text,programado_para timestamptz default null)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();patient public.pacientes;conversation public.conversaciones_whatsapp;item public.mensajes_whatsapp;phone text;begin if actor is null or not public.has_permission('SEGUIMIENTO_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para programar mensajes';end if;select*into patient from public.pacientes p where p.id=paciente_id and p.activo;if not found then raise exception using errcode='P0001',message='Paciente no encontrado';end if;if not patient.whatsapp_autorizado then raise exception using errcode='P0001',message='El paciente no autorizó comunicaciones por WhatsApp';end if;phone:=regexp_replace(coalesce(patient.celular,''),'\D','','g');if length(phone)<7 then raise exception using errcode='P0001',message='El paciente no tiene un celular válido';end if;select*into conversation from public.conversaciones_whatsapp c where c.telefono=phone and c.estado<>'CERRADA'for update;if not found then insert into public.conversaciones_whatsapp(paciente_id,telefono,ultimo_mensaje_en)values(patient.id,phone,now())returning*into conversation;end if;insert into public.mensajes_whatsapp(conversacion_id,paciente_id,direccion,contenido,estado,programado_para,creado_por,tipo)values(conversation.id,patient.id,'SALIENTE',btrim(contenido),'PENDIENTE',coalesce(programado_para,now()),actor,'MANUAL')returning*into item;update public.conversaciones_whatsapp set ultimo_mensaje_en=now(),actualizado_en=now()where id=conversation.id;perform public.registrar_auditoria('PROGRAMAR_MENSAJE','SEGUIMIENTO',item.id::text,'Paciente '||patient.numero_historia);return public.mensaje_json(item);end $$;
create or replace function public.revisar_seguimiento(seguimiento_id bigint,version_actual bigint,confirmacion boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare actor bigint:=public.current_app_user_id();item public.seguimientos_postconsulta;begin if actor is null or not public.has_permission('SEGUIMIENTO_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para revisar seguimientos';end if;if confirmacion is not true then raise exception using errcode='P0001',message='Confirme la revisión profesional';end if;update public.seguimientos_postconsulta set estado='REVISADO',revisado_por=actor,revisado_en=now(),actualizado_en=now(),version=version+1 where id=seguimiento_id and version=version_actual returning*into item;if not found then raise exception using errcode='P0001',message='El seguimiento fue modificado o no existe';end if;perform public.registrar_auditoria('REVISAR_SEGUIMIENTO','SEGUIMIENTO',item.id::text,item.clasificacion);return public.seguimiento_json(item);end $$;

create or replace function public.programar_seguimiento_clinico()returns trigger language plpgsql security definer set search_path=''as $$declare followup public.seguimientos_postconsulta;conversation public.conversaciones_whatsapp;message public.mensajes_whatsapp;patient public.pacientes;phone text;when_value timestamptz:=now()+interval'24 hours';begin if new.estado='FINALIZADA'and old.estado<>'FINALIZADA'then insert into public.seguimientos_postconsulta(paciente_id,atencion_id,programado_para,creado_por)values(new.paciente_id,new.id,when_value,new.aprobado_por)on conflict(atencion_id)do nothing returning*into followup;select*into patient from public.pacientes where id=new.paciente_id;if followup.id is not null and patient.whatsapp_autorizado and patient.celular is not null then phone:=regexp_replace(patient.celular,'\D','','g');select*into conversation from public.conversaciones_whatsapp where telefono=phone and estado<>'CERRADA';if not found then insert into public.conversaciones_whatsapp(paciente_id,telefono)values(patient.id,phone)returning*into conversation;end if;insert into public.mensajes_whatsapp(conversacion_id,paciente_id,atencion_id,direccion,contenido,estado,programado_para,creado_por,tipo,plantilla_nombre)select conversation.id,patient.id,new.id,'SALIENTE',replace(t.contenido,'{{paciente}}',patient.nombres),'PENDIENTE',when_value,new.aprobado_por,'POSTCONSULTA',t.codigo from public.plantillas_mensaje t where t.codigo='POSTCONSULTA'returning*into message;update public.seguimientos_postconsulta set mensaje_id=message.id where id=followup.id;elsif followup.id is not null then update public.seguimientos_postconsulta set estado='CERRADO',clasificacion='SIN_AUTORIZACION_O_CELULAR',actualizado_en=now()where id=followup.id;end if;end if;return new;end $$;
create trigger seguimiento_al_finalizar after update of estado on public.atenciones_clinicas for each row execute function public.programar_seguimiento_clinico();

create or replace function public.registrar_evento_whatsapp(datos jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare item public.mensajes_whatsapp;conversation public.conversaciones_whatsapp;patient public.pacientes;phone text:=regexp_replace(coalesce(datos->>'phone',''),'\D','','g');content text:=btrim(datos->>'content');provider text:=nullif(datos->>'providerId','');intent text;alert text;begin if provider is not null then select*into item from public.mensajes_whatsapp where proveedor_id=provider;if found then return public.mensaje_json(item);end if;end if;select*into patient from public.pacientes where activo and celular is not null and regexp_replace(celular,'\D','','g')=phone limit 1;select*into conversation from public.conversaciones_whatsapp where telefono=phone and estado<>'CERRADA';if not found then insert into public.conversaciones_whatsapp(paciente_id,telefono)values(patient.id,phone)returning*into conversation;end if;intent:=case when lower(content)~'sangrado abundante|no para de sangrar|fiebre|hinchaz(o|ó)n severa|dificultad para respirar|dolor insoportable|alergia'then'ALERTA_CLINICA'when upper(content)~'CONFIRM'then'CONFIRMAR'when upper(content)~'CANCEL'then'CANCELAR'when upper(content)~'REPROGRAM'then'REPROGRAMAR'when upper(content)~'RESERV'then'RESERVAR'else'NO_ENTENDIDO'end;insert into public.mensajes_whatsapp(conversacion_id,paciente_id,direccion,contenido,estado,proveedor_id,intencion,requiere_revision,tipo)values(conversation.id,patient.id,'ENTRANTE',content,'RECIBIDO',provider,intent,patient.id is null or intent<>'AYUDA','ENTRANTE')returning*into item;update public.conversaciones_whatsapp set estado=case when item.requiere_revision then'DERIVADA'else estado end,ultimo_mensaje_en=now(),actualizado_en=now()where id=conversation.id;if patient.id is not null then update public.seguimientos_postconsulta set estado=case when intent='ALERTA_CLINICA'then'ALERTA'else'RESPONDIDO'end,respuesta=content,clasificacion=case when intent='ALERTA_CLINICA'then'REQUIERE_REVISION'else'RESPUESTA_RECIBIDA'end,motivo_alerta=case when intent='ALERTA_CLINICA'then'Alerta clínica detectada en respuesta WhatsApp'end,actualizado_en=now(),version=version+1 where id=(select id from public.seguimientos_postconsulta where paciente_id=patient.id and estado='ENVIADO'order by programado_para desc limit 1);end if;return public.mensaje_json(item);end $$;

revoke all on function public.mensaje_json(public.mensajes_whatsapp),public.seguimiento_json(public.seguimientos_postconsulta),public.listar_mensajes(),public.listar_seguimientos(),public.programar_mensaje(bigint,text,timestamptz),public.revisar_seguimiento(bigint,bigint,boolean),public.programar_seguimiento_clinico(),public.registrar_evento_whatsapp(jsonb)from public;
grant execute on function public.listar_mensajes(),public.listar_seguimientos(),public.programar_mensaje(bigint,text,timestamptz),public.revisar_seguimiento(bigint,bigint,boolean)to authenticated;
grant execute on function public.registrar_evento_whatsapp(jsonb)to service_role;
